using System;using System.IO;using System.Linq;using Microsoft.CodeAnalysis.CSharp;using Microsoft.CodeAnalysis.CSharp.Syntax;using NUnit.Framework;
namespace FUI.Portable.Tests{public sealed class EditorInspectorMemberTests{
[Test]public void ActualInspectorPropertyFieldFragmentCompilesAndReadsInheritedCommand(){var root=GeneratedCompilation.RepositoryRoot();var folder=Path.Combine(root,"Packages/com.fujisheng.fui/Editor");var source=File.ReadAllText(Path.Combine(root,"Packages/com.fujisheng.fui.ugui/Editor/Inspector/BindingInspector.cs"));var imports=string.Join("\n",CSharpSyntaxTree.ParseText(source).GetRoot().DescendantNodes().OfType<UsingDirectiveSyntax>().Where(x=>x.Name.ToString().StartsWith("System")).Select(x=>x.ToFullString()));var start=source.IndexOf("var targetMember = ElementMemberResolver.Resolve",StringComparison.Ordinal);var end=source.IndexOf("DetailsWindow.ShowDetails",start,StringComparison.Ordinal);var fragment=source.Substring(start,end-start);var scenario=imports+@"using System;namespace FUI.Editor.Inspection {public sealed class TargetInfo{public string propertyName;}public sealed class Info{public TargetInfo targetInfo=new TargetInfo();}public static class Probe{public static bool Run(){var button=new FUI.Testing.HeadlessButtonElement(""Button"");var target=(object)button;var targetType=typeof(FUI.Rendering.IButtonElement);var info=new Info();info.targetInfo.propertyName=""Click"";"+fragment+@"return ReferenceEquals(property,button.Click);}}}";var a=GeneratedCompilation.Compile(("ActualEditorMemberResolver.cs",File.ReadAllText(Path.Combine(folder,"Common/ElementMemberResolver.cs"))),("ActualInspectorFragment.cs",scenario));Assert.That((bool)a.GetType("FUI.Editor.Inspection.Probe").GetMethod("Run").Invoke(null,null),Is.True,"Actual Inspector member-reading code in .NET; not Editor UI execution");}
}}
